const TABLE: Record<string, Partial<MessengerText>> = { de, en, ar, tr, ur, fa, ps, fr, es, id, ms, bn, ru, zh };
const cache = new Map<string, MessengerText>();
/** the messenger texts in a language (missing keys fall back to English) */
export function messengerText(lang: string): MessengerText {
  const l = (lang || "en").slice(0, 2);
  let t = cache.get(l);
  if (!t) { t = { ...en, ...(TABLE[l] ?? {}) }; cache.set(l, t); }
  return t;
}
export const fill = (s: string, n: string | number) => s.replace("{n}", String(n));

/** an API error code as a sentence */
export function errorText(t: MessengerText, code: string | undefined | null): string {
  switch (code) {
    case "request_wait": return t.e_request_wait;
    case "request_text_only": return t.e_request_text_only;
    case "request_open": return t.e_request_open;
    case "minor_protection": return t.e_minor_protection;
    case "friends_only": return t.e_friends_only;
    case "group_gender": return t.e_group_gender;
    case "group_full": return t.e_group_full;
    case "invite_invalid": return t.e_invite_invalid;
    case "muted": return t.e_muted;
    case "media_format": case "media_unavailable": return t.e_media;
    case "media_unsafe": return t.e_unsafe;
    case "media_too_large": return t.e_too_large;
    case "text_not_allowed": return t.e_text;
    case "age16": case "age": case "age_required": return t.e_age16;
    case "slow_down": return t.e_slow;
    case "not_found": case "not_available": return t.e_not_found;
    case "name_required": return t.e_name;
    case "view_once_age": case "view_once_direct": return t.e_view_once_age;
    case "view_once_opened": return t.e_view_once_opened;
    case "edit_window": return t.e_edit_window;
    case "pro_required": return t.e_pro;
    case "login": return t.signIn;
    default: return t.e_generic;
  }
}

/** a system line ("@x joined") in the reader's language */
export function systemLine(t: MessengerText, s: { what: string; who: string } | null | undefined): string {
  if (!s) return "";
  const who = `@${s.who}`;
  const k = `sys_${s.what}` as keyof MessengerText;
  return typeof t[k] === "string" ? fill(t[k] as string, who) : who;
}
